  const show = next => { index = Math.max(0, Math.min(steps.length - 1, next)); steps.forEach((step, i) => step.hidden = i !== index); root.querySelector('[data-progress]').textContent = `Step ${index + 1} of ${steps.length}`; root.querySelector('[data-back]').disabled = index === 0; root.querySelector('[data-next]').textContent = index === steps.length - 1 ? 'Submit' : 'Continue'; steps[index].querySelector('legend')?.focus(); };
  root.querySelector('[data-next]').addEventListener('click', () => { const field = steps[index].querySelector(':invalid'); if (field) return field.reportValidity(); if (index < steps.length - 1) show(index + 1); else root.requestSubmit(); });
