inline-validation.js:
const root = document.querySelector('.fx-inline-validation');
if (root) {
  const input = root.querySelector('input');
  const error = root.querySelector('.fx-inline-validation__error');
  const validate = () => {
    const valid = input.validity.valid;
    input.setAttribute('aria-invalid', String(!valid));
    error.textContent = valid ? '' : input.validity.valueMissing ? 'Enter your work email.' : 'Enter an email in the format name@example.com.';
    return valid;
  };
  input?.addEventListener('blur', validate);
  input?.addEventListener('input', () => { if (input.getAttribute('aria-invalid') === 'true') validate(); });
  root.addEventListener('submit', event => { event.preventDefault(); if (!validate()) input.focus(); });
}

