context-menu.js:
const root = document.querySelector('.fx-context-menu');
if (root) {
  const trigger = root.querySelector('[data-trigger]');
  const menu = root.querySelector('[role="menu"]');
  const items = [...root.querySelectorAll('[role="menuitem"]')];
  const setOpen = open => {
    menu.hidden = !open;
    trigger.setAttribute('aria-expanded', String(open));
    if (open) items[0]?.focus(); else trigger.focus();
  };
  trigger?.addEventListener('click', () => setOpen(menu.hidden));
  trigger?.addEventListener('keydown', event => {
    if (event.key === 'F10' && event.shiftKey) { event.preventDefault(); setOpen(true); }
  });
  menu?.addEventListener('keydown', event => {
    const index = items.indexOf(document.activeElement);
    if (event.key === 'Escape') { event.preventDefault(); setOpen(false); }
    if (event.key === 'ArrowDown') { event.preventDefault(); items[(index + 1) % items.length].focus(); }
    if (event.key === 'ArrowUp') { event.preventDefault(); items[(index - 1 + items.length) % items.length].focus(); }
    if (event.key === 'Home') { event.preventDefault(); items[0].focus(); }
    if (event.key === 'End') { event.preventDefault(); items.at(-1).focus(); }
  });
  document.addEventListener('pointerdown', event => { if (!root.contains(event.target) && !menu.hidden) setOpen(false); });
}

