const root = document.querySelector('.fx-drag-reorder');
if (root) {
  const list = root.querySelector('ol');
  const status = root.querySelector('[role="status"]');
  let dragged = null;
  const announce = item => {
    const items = [...list.children];
    if (status) status.textContent = item.querySelector('span').textContent + ' moved to position ' + (items.indexOf(item) + 1) + ' of ' + items.length + '.';
  };
  list?.addEventListener('click', event => {
    const button = event.target.closest('button');
    const item = button?.closest('li');
    if (!item) return;
    if (button.matches('[data-up]') && item.previousElementSibling) list.insertBefore(item, item.previousElementSibling);
    if (button.matches('[data-down]') && item.nextElementSibling) list.insertBefore(item.nextElementSibling, item);
    announce(item);
  });
  list?.addEventListener('dragstart', event => { dragged = event.target.closest('li'); if (dragged) dragged.dataset.dragging = 'true'; });
  list?.addEventListener('dragover', event => { event.preventDefault(); const over = event.target.closest('li'); if (dragged && over && over !== dragged) list.insertBefore(dragged, over); });
  list?.addEventListener('dragend', () => { if (dragged) { delete dragged.dataset.dragging; announce(dragged); } dragged = null; });
}

