const root = document.querySelector('.fx-filter-sidebar');
if (root) {
  const form = root.querySelector('form');
  const cards = [...root.querySelectorAll('article')];
  const count = root.querySelector('[data-count]');
  const empty = root.querySelector('[data-empty]');
  const apply = () => {
    const data = new FormData(form);
    const categories = data.getAll('category');
    const stockOnly = data.has('stock');
    let visible = 0;
    cards.forEach(card => {
      const show = (!categories.length || categories.includes(card.dataset.category)) && (!stockOnly || card.dataset.stock === 'available');
      card.hidden = !show;
      if (show) visible++;
    });
    if (count) count.textContent = String(visible);
    if (empty) empty.hidden = visible !== 0;
  };
  form?.addEventListener('change', apply);
  form?.addEventListener('reset', () => requestAnimationFrame(apply));
}

