desktop-wizard.js:
const root = document.querySelector('.fx-desktop-wizard');
if (root) {
  const steps = [...root.querySelectorAll('[data-step]')];
  const labels = [...root.querySelectorAll('nav li')];
  const back = root.querySelector('[data-back]');
  const next = root.querySelector('[data-next]');
  const status = root.querySelector('[role="status"]');
  let index = 0;
  const show = value => {
    index = Math.max(0, Math.min(steps.length - 1, value));
    steps.forEach((step, i) => step.hidden = i !== index);
    labels.forEach((label, i) => i === index ? label.setAttribute('aria-current','step') : label.removeAttribute('aria-current'));
    back.disabled = index === 0;
    next.textContent = index === steps.length - 1 ? 'Create workspace' : 'Continue';
    if (status) status.textContent = 'Step ' + (index + 1) + ' of ' + steps.length + ': ' + labels[index].textContent;
    steps[index].querySelector('input')?.focus();
  };
  back?.addEventListener('click', () => show(index - 1));
  next?.addEventListener('click', () => {
    const field = steps[index].querySelector('input');
    if (field && !field.reportValidity()) return;
    if (index < steps.length - 1) show(index + 1);
    else if (status) status.textContent = 'Workspace created.';
  });
}

