const root = document.querySelector('.fx-carousel');
if (root) {
  const track = root.querySelector('.fx-carousel__track');
  const slides = [...root.querySelectorAll('article')];
  const status = root.querySelector('.fx-carousel__status');
  const go = delta => {
    const width = slides[0]?.getBoundingClientRect().width || 0;
    track?.scrollBy({left:delta * (width + 16), behavior:'smooth'});
  };
  root.querySelector('[data-prev]')?.addEventListener('click', () => go(-1));
  root.querySelector('[data-next]')?.addEventListener('click', () => go(1));
  track?.addEventListener('scrollend', () => {
    const index = slides.reduce((best, slide, i) => Math.abs(slide.offsetLeft - track.scrollLeft) < Math.abs(slides[best].offsetLeft - track.scrollLeft) ? i : best, 0);
    if (status) status.textContent = 'Slide ' + (index + 1) + ' of ' + slides.length;
  });
}

