layered-parallax.js:
const root = document.querySelector('.fx-layered-parallax');
if (root && !matchMedia('(prefers-reduced-motion: reduce)').matches) {
  const layers = [...root.querySelectorAll('[data-depth]')];
  const move = event => {
    const rect = root.getBoundingClientRect();
    const x = event.clientX - rect.left - rect.width / 2;
    const y = event.clientY - rect.top - rect.height / 2;
    layers.forEach(layer => {
      const depth = Number(layer.dataset.depth);
      layer.style.setProperty('--x', x * depth + 'px');
      layer.style.setProperty('--y', y * depth + 'px');
    });
  };
  root.addEventListener('pointermove', move);
  root.addEventListener('pointerleave', () => layers.forEach(layer => { layer.style.setProperty('--x','0px'); layer.style.setProperty('--y','0px'); }));
}

