cursor-trail.js:
const root = document.querySelector('.fx-cursor-trail');
if (root && !matchMedia('(prefers-reduced-motion: reduce)').matches) {
  const dots = [...root.querySelectorAll('.fx-cursor-trail__dot')];
  const points = dots.map(() => ({x:-32,y:-32}));
  let target = {x:-32,y:-32};
  let frame = 0;
  const render = () => {
    points.forEach((point, index) => {
      const lead = index ? points[index - 1] : target;
      point.x += (lead.x - point.x) * .42;
      point.y += (lead.y - point.y) * .42;
      dots[index].style.transform = 'translate3d(' + point.x + 'px,' + point.y + 'px,0)';
    });
    frame = requestAnimationFrame(render);
  };
  root.addEventListener('pointerenter', () => { root.dataset.moving = 'true'; if (!frame) render(); });
  root.addEventListener('pointermove', event => {
    const rect = root.getBoundingClientRect();
    target = {x:event.clientX - rect.left,y:event.clientY - rect.top};
  });
  root.addEventListener('pointerleave', () => { delete root.dataset.moving; cancelAnimationFrame(frame); frame = 0; });
}

