    if (heading) heading.textContent = weekly ? 'This week' : 'Today';
    if (copy) copy.textContent = weekly ? '42 tasks completed · 7 reviews pending' : '8 tasks completed · 2 reviews pending';
    if (button) button.textContent = weekly ? 'Show daily view' : 'Show weekly view';
  };
