.fx-favorite-burst h2 { margin:.2rem 0 0; font-size:1.3rem; }
.fx-favorite-burst button { position:absolute; right:1rem; top:50%; width:3rem; height:3rem; display:grid; place-items:center; border:1px solid #fda4af; border-radius:50%; color:#be123c; background:#fff1f2; font-size:1.35rem; cursor:pointer; transition:transform .18s ease; }
.fx-favorite-burst button:hover { transform:scale(1.08); }
.fx-favorite-burst button[aria-pressed="true"] { color:#fff; background:#e11d48; animation:fx-favorite-pop .45s cubic-bezier(.2,.9,.3,1.4); }
.fx-favorite-burst button i, .fx-favorite-burst button i::before, .fx-favorite-burst button i::after { position:absolute; inset:50%; width:.35rem; height:.35rem; border-radius:50%; pointer-events:none; background:#fb7185; opacity:0; }
.fx-favorite-burst button[aria-pressed="true"] i { animation:fx-favorite-ray .5s ease-out; }
.fx-favorite-burst button[aria-pressed="true"] i::before { content:""; transform:rotate(60deg); animation:fx-favorite-ray .5s ease-out; }
.fx-favorite-burst button[aria-pressed="true"] i::after { content:""; transform:rotate(120deg); animation:fx-favorite-ray .5s ease-out; }
.fx-favorite-burst__label { position:absolute; width:1px; height:1px; overflow:hidden; clip-path:inset(50%); }
.fx-favorite-burst > [role="status"] { min-height:1.5em; margin:.35rem 0 0; color:#526078; font-size:.875rem; }
@keyframes fx-favorite-pop { 45% { transform:scale(1.25); } }
@keyframes fx-favorite-ray { 0% { box-shadow:0 0 #fb7185,0 0 #fda4af; opacity:1; } 100% { box-shadow:1.8rem 0 #fb7185,-1.8rem 0 #fda4af; opacity:0; } }
.fx-favorite-burst :focus-visible { outline:3px solid #2563eb; outline-offset:3px; }
@media (prefers-reduced-motion: reduce) {
  .fx-favorite-burst,
  .fx-favorite-burst * { scroll-behavior:auto !important; animation-duration:.01ms !important; animation-iteration-count:1 !important; transition-duration:.01ms !important; }
}

favorite-burst.js:
const root = document.querySelector('.fx-favorite-burst');
if (root) {
  const button = root.querySelector('button');
  const label = root.querySelector('.fx-favorite-burst__label');
  const status = root.querySelector('[role="status"]');
  button?.addEventListener('click', () => {
    const pressed = button.getAttribute('aria-pressed') !== 'true';
    button.setAttribute('aria-pressed', String(pressed));
    if (label) label.textContent = pressed ? 'Remove from favorites' : 'Add to favorites';
    if (status) status.textContent = pressed ? 'Added to favorites.' : 'Removed from favorites.';
  });
}

