copy-confirmation.js:
const root = document.querySelector('.fx-copy-confirmation');
if (root) {
  const button = root.querySelector('[data-copy]');
  const status = root.querySelector('[role="status"]');
  button?.addEventListener('click', async () => {
    const value = root.querySelector('code')?.textContent || '';
    try {
      await navigator.clipboard.writeText(value);
      button.textContent = 'Copied';
      button.dataset.copied = 'true';
      if (status) status.textContent = 'Command copied to clipboard.';
      window.setTimeout(() => { button.textContent = 'Copy'; delete button.dataset.copied; }, 1800);
    } catch {
      if (status) status.textContent = 'Copy failed. Select the command and copy it manually.';
    }
  });
}

spotlight-follow.js:
const root = document.querySelector('.fx-spotlight-follow');
if (root && !matchMedia('(prefers-reduced-motion: reduce)').matches && matchMedia('(hover: hover) and (pointer: fine)').matches) {
  let frame = 0;
  let point = { x: 0, y: 0 };
  const paint = () => { frame = 0; const box = root.getBoundingClientRect(); root.style.setProperty('--fx-x', point.x - box.left + 'px'); root.style.setProperty('--fx-y', point.y - box.top + 'px'); };
  root.addEventListener('pointerenter', () => { root.dataset.active = 'true'; });
  root.addEventListener('pointermove', event => { point = { x: event.clientX, y: event.clientY }; if (!frame) frame = requestAnimationFrame(paint); });
  root.addEventListener('pointerleave', () => { delete root.dataset.active; if (frame) cancelAnimationFrame(frame); frame = 0; });
}

hover-ripple-feedback.js:
const root = document.querySelector('.fx-hover-ripple-feedback');
if (root) {
  const button = root.querySelector('button');
  const ripple = root.querySelector('.fx-hover-ripple-feedback__ripple');
  const status = root.querySelector('[role="status"]');
  button.addEventListener('click', event => {
    if (status) status.textContent = 'Review marked complete.';
    if (matchMedia('(prefers-reduced-motion: reduce)').matches) return;
    const box = button.getBoundingClientRect();
    const keyboard = event.detail === 0;
    button.style.setProperty('--fx-ripple-x', (keyboard ? box.width / 2 : event.clientX - box.left) + 'px');
    button.style.setProperty('--fx-ripple-y', (keyboard ? box.height / 2 : event.clientY - box.top) + 'px');
    ripple.classList.remove('is-active');
    requestAnimationFrame(() => ripple.classList.add('is-active'));
  });
  ripple.addEventListener('animationend', () => ripple.classList.remove('is-active'));
}

