list-reorder-flip.js:
const root = document.querySelector('.fx-list-reorder-flip');
if (root) {
  const list = root.querySelector('ol');
  const status = root.querySelector('[role="status"]');
  list.addEventListener('click', event => {
    const button = event.target.closest('button'); const item = button && button.closest('li'); if (!item) return;
    const before = new Map([...list.children].map(node => [node, node.getBoundingClientRect()]));
    if (button.matches('[data-up]') && item.previousElementSibling) list.insertBefore(item, item.previousElementSibling);
    else if (button.matches('[data-down]') && item.nextElementSibling) list.insertBefore(item.nextElementSibling, item);
    else return;
    if (!matchMedia('(prefers-reduced-motion: reduce)').matches) [...list.children].forEach(node => { const first = before.get(node); const last = node.getBoundingClientRect(); node.animate([{ transform: 'translateY(' + (first.top - last.top) + 'px)' }, { transform: 'translateY(0)' }], { duration: 260, easing: 'cubic-bezier(.2,.8,.2,1)' }); });
    const items = [...list.children]; status.textContent = item.querySelector('span').textContent + ' moved to position ' + (items.indexOf(item) + 1) + ' of ' + items.length + '.'; button.focus();
  });
}

page-turn-transition.js:
const root = document.querySelector('.fx-page-turn-transition');
if (root) {
  const pages = [...root.querySelectorAll('article')]; let index = 0;
  const show = (next, back) => { index = (next + pages.length) % pages.length; pages.forEach((page, pageIndex) => { const active = pageIndex === index; page.classList.toggle('is-active', active); page.classList.toggle('is-back', active && back); page.setAttribute('aria-hidden', String(!active)); }); };
  root.querySelector('[data-prev]').addEventListener('click', () => show(index - 1, true));
  root.querySelector('[data-next]').addEventListener('click', () => show(index + 1, false));
}

hero-expand-navigation.js:
const root = document.querySelector('.fx-hero-expand-navigation');
if (root) {
  const items = [
    { kicker: 'Coast route', title: 'Slate Harbor', copy: 'Walk the western breakwater before the afternoon tide.', theme: '' },
    { kicker: 'Forest route', title: 'Cedar Basin', copy: 'Follow the shaded loop to the old survey station.', theme: 'forest' },
    { kicker: 'City route', title: 'Night Archive', copy: 'Trace reflected signs through the warehouse district.', theme: 'city' }
  ];
  const panel = root.querySelector('article'); const buttons = [...root.querySelectorAll('nav button')];
  buttons.forEach(button => button.addEventListener('click', () => { const index = Number(button.dataset.index); const item = items[index]; buttons.forEach(candidate => candidate.setAttribute('aria-pressed', String(candidate === button))); root.querySelector('[data-kicker]').textContent = item.kicker; root.querySelector('[data-title]').textContent = item.title; root.querySelector('[data-copy]').textContent = item.copy; panel.dataset.theme = item.theme; if (!matchMedia('(prefers-reduced-motion: reduce)').matches) { panel.style.animation = 'none'; requestAnimationFrame(() => { panel.style.animation = ''; }); } }));
}

confetti-success-burst.js:
const root = document.querySelector('.fx-confetti-success-burst');
if (root) {
  const button = root.querySelector('button'); const pieces = root.querySelector('.fx-confetti-success-burst__pieces'); const status = root.querySelector('[role="status"]');
  button.addEventListener('click', () => {
    status.textContent = 'Release published successfully.';
    if (matchMedia('(prefers-reduced-motion: reduce)').matches) return;
    const colors = ['#2563eb','#0f766e','#f59e0b','#db2777'];
    for (let index = 0; index < 18; index += 1) { const piece = document.createElement('span'); piece.className = 'fx-confetti-success-burst__piece'; piece.style.setProperty('--fx-color', colors[index % colors.length]); piece.style.setProperty('--fx-x', Math.round((Math.random() - .5) * 260) + 'px'); piece.style.setProperty('--fx-y', Math.round(-40 - Math.random() * 150) + 'px'); piece.style.setProperty('--fx-r', Math.round(Math.random() * 540) + 'deg'); piece.style.animationDelay = index * 12 + 'ms'; piece.addEventListener('animationend', () => piece.remove()); pieces.append(piece); }
  });
}

shake-validation-error.js:
const root = document.querySelector('.fx-shake-validation-error');
if (root) {
  const input = root.querySelector('input'); const error = root.querySelector('[role="alert"]');
  const validate = () => { const valid = input.validity.valid; input.setAttribute('aria-invalid', String(!valid)); error.textContent = valid ? '' : input.validity.valueMissing ? 'Enter your work email.' : 'Use the format name@example.com.'; return valid; };
  root.addEventListener('submit', event => { event.preventDefault(); if (validate()) { error.textContent = 'Access request ready.'; return; } input.focus(); if (!matchMedia('(prefers-reduced-motion: reduce)').matches) { root.classList.remove('is-shaking'); requestAnimationFrame(() => root.classList.add('is-shaking')); } });
  input.addEventListener('input', () => { if (input.getAttribute('aria-invalid') === 'true') validate(); });
  input.addEventListener('animationend', () => root.classList.remove('is-shaking'));
}

progress-ring-completion.js:
const root = document.querySelector('.fx-progress-ring-completion');
if (root) {
  const range = root.querySelector('input'); const value = root.querySelector('[data-value]'); const status = root.querySelector('[role="status"]'); const circumference = 2 * Math.PI * 50;
  const update = () => { const percent = Number(range.value); root.style.setProperty('--fx-ring-offset', circumference * (1 - percent / 100)); value.textContent = percent + '%'; status.textContent = percent === 100 ? 'Profile complete.' : percent + ' percent complete.'; };
  range.addEventListener('input', update); update();
}

long-press-context-reveal.js:
const root = document.querySelector('.fx-long-press-context-reveal');
if (root) {
  const item = root.querySelector('[data-item]'); const more = root.querySelector('[data-more]'); const menu = root.querySelector('[role="menu"]'); const choices = [...root.querySelectorAll('[role="menuitem"]')]; const status = root.querySelector('[role="status"]'); let timer = 0;
  const setOpen = open => { menu.hidden = !open; more.setAttribute('aria-expanded', String(open)); if (open) choices[0].focus(); };
  const start = event => { if (event.pointerType === 'mouse' && event.button !== 0) return; item.dataset.pressing = 'true'; timer = setTimeout(() => { timer = 0; delete item.dataset.pressing; setOpen(true); }, 600); };
  const cancel = () => { if (timer) clearTimeout(timer); timer = 0; delete item.dataset.pressing; };
  item.addEventListener('pointerdown', start); item.addEventListener('pointerup', cancel); item.addEventListener('pointercancel', cancel); item.addEventListener('pointerleave', cancel);
  item.addEventListener('keydown', event => { if (event.key === 'F10' && event.shiftKey) { event.preventDefault(); setOpen(true); } });
  more.addEventListener('click', () => setOpen(menu.hidden));
  menu.addEventListener('keydown', event => { const index = choices.indexOf(document.activeElement); if (event.key === 'Escape') { event.preventDefault(); setOpen(false); more.focus(); } if (event.key === 'ArrowDown') { event.preventDefault(); choices[(index + 1) % choices.length].focus(); } if (event.key === 'ArrowUp') { event.preventDefault(); choices[(index - 1 + choices.length) % choices.length].focus(); } });
  menu.addEventListener('click', event => { const choice = event.target.closest('[role="menuitem"]'); if (!choice) return; status.textContent = choice.textContent + ' selected for Quarterly-notes.txt.'; setOpen(false); more.focus(); });
}
